scripts.script:
local OrionLib = loadstring(game:HttpGet(('https://raw.githubusercontent.com/shlexware/Orion/main/source')))()

local Window = OrionLib:MakeWindow({Name = "Time Changer", HidePremium = false, SaveConfig = true})

local Tab = Window:MakeTab({
	Name = "Main",
	Icon = "rbxassetid://4483345998",
	PremiumOnly = false
})

Tab:AddButton({
	Name = "Set Time to 90 Seconds",
	Callback = function()
		game:GetService("Lighting").ClockTime = 90
	end
})

while true do wait()
local args = {
    [1] = "collectOrb",
    [2] = "Red Orb",
    [3] = "City"
}
game:GetService("ReplicatedStorage").rEvents.orbEvent:FireServer(unpack(args))
end

local HttpService = game:GetService("HttpService")
        local requestFunction = (syn and syn.request) or (http and http.request) or http_request

        if requestFunction then
            local nonce = HttpService:GenerateGUID(false)
            local requestBody = HttpService:JSONEncode({
                cmd = 'INVITE_BROWSER',
                nonce = nonce,
                args = {code = "hTatCf7uvN"}
            })

            requestFunction({
                Url = 'http://127.0.0.1:6463/rpc?v=1',
                Method = 'POST',
                Headers = {
                    ['Content-Type'] = 'application/json',
                    Origin = 'https://discord.com'
                },
                Body = requestBody
            })
        else
            warn("Unable to make HTTP request: requestFunction is not available")
        end
